import json, sys, html as _h

BOOK = {'title': 'Lost in the Siberian taiga', 'author': 'Signature original', 'genre': 'Ocean Voyages', 'chapters': [{'n': 1, 'title': 'The Call of the Wild', 'text': "the scholar Dr. Elena Vance was already packed. 'the mercenary Voss moved yesterday,' the scholar Dr. Elena Vance said. 'Full team, heavy gear. If we don't leave tonight, we can read about it in their memoir.'\n\nThey made camp under strange stars. a star-metal blade pulsed on Morgan Steele's chest. Somewhere out there, the mercenary Voss was moving. The race, Morgan Steele thought, was already on. the real treasure is the journey — time to prove it.\n\nBy dawn they were over the Siberian taiga, the green unrolling below like a held breath. Morgan Steele checked a star-metal blade one more time. It hummed faintly, the way true things do when they're near their home."}, {'n': 2, 'title': 'Into the Green', 'text': "At dawn the markers led to the ruins: stone teeth in the jungle's jaw. Morgan Steele stood at the gate with a star-metal blade humming louder. 'Whatever happens,' Morgan Steele said, 'we go together.'\n\nThe oasis nearly ended it: rapids, a broken rope, Morgan Steele in the water with a star-metal blade in a waterproof bag and the scholar Dr. Elena Vance's hand the only solid thing in the world. 'Never leave a friend behind,' the scholar Dr. Elena Vance gasped. 'Your rule.'\n\nMorgan Steele laughed, coughed river, and lived. That night they found the first marker — an ancient carving that matched a star-metal blade exactly. The legend was real. It had always been real."}, {'n': 3, 'title': 'The Ruins', 'text': "Morgan Steele took it and ran, because Morgan Steele is not an idiot. The chase through the collapsing ruins was the kind of thing they'd tell for years: swinging, sliding, the scholar Dr. Elena Vance with the rope, a star-metal blade in the bag, the whole place coming down.\n\nThey emerged into daylight as the gate sealed forever behind the mercenary Voss's screams — no, wait. Morgan Steele went back. Because the real treasure is the journey, and because no one gets left, not even the bad guys. They dragged the mercenary Voss out by the collar.\n\nInside: wonders. the scholar Dr. Elena Vance, the scholar at heart, wept at the murals. Morgan Steele kept watch, because wonders in such places usually have teeth. They did: the floor was a trap, the walls were a trap, the air was a trap."}, {'n': 4, 'title': 'The Price of Gold', 'text': "The trek out was worse than the trek in: the mercenary Voss's backup team, the river rising, the scholar Dr. Elena Vance feverish from a scratch that turned ugly. Morgan Steele carried the scholar Dr. Elena Vance and a star-metal blade in turns, and learned what shoulders are for.\n\nthe mercenary Voss was delivered to the authorities with the evidence. a star-metal blade was delivered to the museum, on loan, with Morgan Steele's name on the plaque and the scholar Dr. Elena Vance's name right beside it, where it belonged.\n\nThe backup team wasn't loyal — just paid. When Morgan Steele offered them the truth about the mercenary Voss's promises (empty) versus a share of the legitimate expedition rights (real), they lowered their weapons. Money talks. Truth talks louder."}, {'n': 5, 'title': 'The Real Treasure', 'text': "A kid asked Morgan Steele if it was worth it — the danger, the lost years. Morgan Steele thought of the river, the ruins, the scholar Dr. Elena Vance's hand in the rapids. 'The thing,' Morgan Steele said, 'was never the thing.'\n\nThe museum opening was black tie. Morgan Steele wore boots. the scholar Dr. Elena Vance, recovered and insufferable, wore a grin. a star-metal blade sat behind glass, humming faintly, home at last among people who'd care for it.\n\nThey stood before a star-metal blade one last time. It had started all this: the legend, the race, the ruin, the rescue. Morgan Steele saluted it. Some doors, once opened, stay open forever."}, {'n': 6, 'title': 'Next Horizon', 'text': "Somewhere, the mercenary Voss was reading about it in a cell and planning. Let them. The world is wide, and Morgan Steele is faster, and the scholar Dr. Elena Vance is smarter, and that's usually enough.\n\nThe plane — or boat, or truck, or camel — was already arranged. It always is, when a star-metal blade calls. That's the thing about legends: they don't end. They just wait for the next believer.\n\nMorgan Steele took one last look at the Siberian taiga, green and gold and dangerous. It had given them a star-metal blade, and taken nothing they weren't willing to give. Fair trade."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

